# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""Out-of-place foreach true division of a tensor list by a paired scalar list.

Architecture:
  * contiguous tensors are grouped by (device, dtype) and fused up to
    _MAX_T per launch so one Triton launch serves a whole homogeneous chunk
    (per-branch bodies because this backend cannot select pointers with
    arith.select);
  * the launch tile is derived from the chunk's element count (wide tile for
    large tensors, narrow tile so small tensors still spread over several
    programs);
  * noncontiguous tensors use a strided-gather kernel (correctness path);
  * zero-element tensors only allocate their output.
Division is IEEE true division with float32 opmath, matching ATen's scalar op.
"""

import numbers

import torch
import triton
import triton.language as tl

_BLOCK_BIG = 8192
_BLOCK_SMALL = 4096
_BLOCK_STRIDED = 1024
_SMALL_LIMIT = 32768
_MAX_T = 4
_MAX_RANK = 8


@triton.jit
def _div_contig_kernel(x_ptr, out_ptr, scalar, n_elem, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n_elem
    x = tl.load(x_ptr + offs, mask=mask, other=0.0)
    y = x.to(tl.float32) / scalar
    tl.store(out_ptr + offs, y, mask=mask)


@triton.jit
def _div_fused4_kernel(
    x0,
    x1,
    x2,
    x3,
    o0,
    o1,
    o2,
    o3,
    s0,
    s1,
    s2,
    s3,
    n0,
    n1,
    n2,
    n3,
    c1,
    c2,
    c3,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    if pid < c1:
        offs = pid * BLOCK + tl.arange(0, BLOCK)
        mask = offs < n0
        x = tl.load(x0 + offs, mask=mask, other=0.0)
        y = x.to(tl.float32) / s0
        tl.store(o0 + offs, y, mask=mask)
    elif pid < c2:
        offs = (pid - c1) * BLOCK + tl.arange(0, BLOCK)
        mask = offs < n1
        x = tl.load(x1 + offs, mask=mask, other=0.0)
        y = x.to(tl.float32) / s1
        tl.store(o1 + offs, y, mask=mask)
    elif pid < c3:
        offs = (pid - c2) * BLOCK + tl.arange(0, BLOCK)
        mask = offs < n2
        x = tl.load(x2 + offs, mask=mask, other=0.0)
        y = x.to(tl.float32) / s2
        tl.store(o2 + offs, y, mask=mask)
    else:
        offs = (pid - c3) * BLOCK + tl.arange(0, BLOCK)
        mask = offs < n3
        x = tl.load(x3 + offs, mask=mask, other=0.0)
        y = x.to(tl.float32) / s3
        tl.store(o3 + offs, y, mask=mask)


@triton.jit
def _div_strided_kernel(
    x_ptr,
    out_ptr,
    scalar,
    n_elem,
    s0,
    s1,
    s2,
    s3,
    s4,
    s5,
    s6,
    s7,
    d0,
    d1,
    d2,
    d3,
    d4,
    d5,
    d6,
    d7,
    t0,
    t1,
    t2,
    t3,
    t4,
    t5,
    t6,
    t7,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    i = pid * BLOCK + tl.arange(0, BLOCK)
    mask = i < n_elem
    off = (i // d0 % s0) * t0
    off += (i // d1 % s1) * t1
    off += (i // d2 % s2) * t2
    off += (i // d3 % s3) * t3
    off += (i // d4 % s4) * t4
    off += (i // d5 % s5) * t5
    off += (i // d6 % s6) * t6
    off += (i // d7 % s7) * t7
    x = tl.load(x_ptr + off, mask=mask, other=0.0)
    y = x.to(tl.float32) / scalar
    tl.store(out_ptr + i, y, mask=mask)


def _strided_args(t):
    shape = list(t.shape)
    stride = list(t.stride())
    rank = len(shape)
    if rank > _MAX_RANK:
        raise RuntimeError("foreach_div: tensor rank above supported maximum")
    shapes = [1] * _MAX_RANK
    divisors = [1] * _MAX_RANK
    strides = [0] * _MAX_RANK
    for d in range(rank):
        shapes[d] = int(shape[d])
        strides[d] = int(stride[d])
    acc = 1
    for d in range(rank - 1, -1, -1):
        divisors[d] = acc
        acc *= shapes[d]
    return shapes, divisors, strides


def _launch_contig(t, out, scalar, n_elem):
    block = _BLOCK_BIG if n_elem >= _SMALL_LIMIT else _BLOCK_SMALL
    grid = (triton.cdiv(n_elem, block),)
    _div_contig_kernel[grid](t, out, scalar, n_elem, BLOCK=block)


def _launch_strided(t, out, scalar, n_elem):
    shapes, divisors, strides = _strided_args(t)
    grid = (triton.cdiv(n_elem, _BLOCK_STRIDED),)
    _div_strided_kernel[grid](
        t,
        out,
        scalar,
        n_elem,
        *shapes,
        *divisors,
        *strides,
        BLOCK=_BLOCK_STRIDED,
    )


def _launch_fused(chunk, tensors, outs, values):
    xs = [tensors[j] for j in chunk]
    os_ = [outs[j] for j in chunk]
    ss = [values[j] for j in chunk]
    ns = [t.numel() for t in xs]
    block = _BLOCK_BIG if max(ns) >= _SMALL_LIMIT else _BLOCK_SMALL
    cum = []
    total = 0
    for v in ns:
        total += (v + block - 1) // block
        cum.append(total)
    while len(xs) < _MAX_T:
        xs.append(xs[0])
        os_.append(os_[0])
        ss.append(0.0)
        ns.append(0)
        cum.append(total)
    _div_fused4_kernel[(total,)](
        xs[0],
        xs[1],
        xs[2],
        xs[3],
        os_[0],
        os_[1],
        os_[2],
        os_[3],
        ss[0],
        ss[1],
        ss[2],
        ss[3],
        ns[0],
        ns[1],
        ns[2],
        ns[3],
        cum[0],
        cum[1],
        cum[2],
        BLOCK=block,
    )


def _normalize_scalars(scalars, n):
    if isinstance(scalars, torch.Tensor):
        if scalars.dim() == 0:
            return [float(scalars.item())] * n
        vals = [float(v) for v in scalars.reshape(-1).tolist()]
    elif isinstance(scalars, numbers.Number):
        return [float(scalars)] * n
    else:
        vals = [float(v) for v in scalars]
    if len(vals) != n:
        raise RuntimeError(
            "Tensor list must have same number of elements as scalar list."
        )
    return vals


def foreach_div_scalar_list(self, scalars):
    if isinstance(self, torch.Tensor):
        tensors = [self]
    else:
        tensors = list(self)
    n = len(tensors)
    values = _normalize_scalars(scalars, n)
    outs = [None] * n
    groups = {}
    for i in range(n):
        t = tensors[i]
        outs[i] = torch.empty(t.shape, dtype=t.dtype, device=t.device)
        n_elem = t.numel()
        if n_elem == 0:
            continue
        if t.is_contiguous():
            key = (t.device, t.dtype)
            bucket = groups.get(key)
            if bucket is None:
                groups[key] = [i]
            else:
                bucket.append(i)
        else:
            _launch_strided(t, outs[i], values[i], n_elem)
    for idxs in groups.values():
        if len(idxs) == 1:
            j = idxs[0]
            _launch_contig(tensors[j], outs[j], values[j], tensors[j].numel())
            continue
        for start in range(0, len(idxs), _MAX_T):
            chunk = idxs[start : start + _MAX_T]
            if len(chunk) == 1:
                j = chunk[0]
                _launch_contig(tensors[j], outs[j], values[j], tensors[j].numel())
            else:
                _launch_fused(chunk, tensors, outs, values)
    return outs
